mapper.select:
select alert_id, level, content, source, occur_time, status, resolved_at, resolved_by,
       legacy_firebase_id, create_by, create_time, update_by, update_time, remark
from pv_alert

    and alert_id = #{alertId}
    and level = #{level}
    and status = #{status}
    and content like concat('%', #{content}, '%')
    and source like concat('%', #{source}, '%')

order by occur_time desc, alert_id desc

mapper.insert:
insert into pv_alert (
    level, content, source, occur_time, status, resolved_at, resolved_by, legacy_firebase_id,
    remark, create_by, create_time
) values (
    #{level}, #{content}, #{source}, #{occurTime}, #{status}, #{resolvedAt}, #{resolvedBy},
    #{legacyFirebaseId}, #{remark}, #{createBy}, #{createTime}
)
